#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Hosted setup for Cardwise: Supabase prod + dev, sign-in, Vercel web project,
# and free model keys. Values are recorded in .env.hosted (git-ignored); the dev
# model keys also go to .env, and the web variables are set in Vercel via its CLI.
# Reference: docs/external-services.md. Run from the repo root in Git Bash.

ENV_FILE=".env.hosted"
TOTAL_STAGES=12

cd "$(git rev-parse --show-toplevel)"

banner "Cardwise hosted setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "GitHub: commit email"
say "Vercel Hobby deploys a private repo only for commits by the account owner."
say "This repo commits as: $(git config user.email)"
open_url "https://github.com/settings/emails"
step "Check that this email is listed and verified on your GitHub account."
step "If it isn't, add and verify it now."
pause "Done? Press Enter"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Supabase: organization and production project"
open_url "https://supabase.com/dashboard/new"
step "Sign in with GitHub. Create an organization named Cardwise, plan Free."
step "New project: name cardwise-prod, region East US (North Virginia)."
step "Database password: Generate, then save it in your password manager."
step "Security options: Data API on, 'Automatically expose new tables' OFF,"
step "'Enable automatic RLS' ON. Create the project."
note "The project ref is the id in the URL: supabase.com/dashboard/project/<ref>"
ask SUPABASE_PROD_REF "Paste the cardwise-prod project ref:"
write_env SUPABASE_PROD_REF "$SUPABASE_PROD_REF"
SUPABASE_PROD_URL="https://${SUPABASE_PROD_REF}.supabase.co"
write_env SUPABASE_PROD_URL "$SUPABASE_PROD_URL"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: development project"
open_url "https://supabase.com/dashboard/new"
step "Same organization. New project: name cardwise-dev, same region."
step "Generate a different database password and save it."
step "Same security options: expose new tables OFF, automatic RLS ON."
ask SUPABASE_DEV_REF "Paste the cardwise-dev project ref:"
write_env SUPABASE_DEV_REF "$SUPABASE_DEV_REF"
SUPABASE_DEV_URL="https://${SUPABASE_DEV_REF}.supabase.co"
write_env SUPABASE_DEV_URL "$SUPABASE_DEV_URL"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase: publishable keys"
say "The publishable key is public by design; the web app sends it to the browser."
warn "Never copy the secret key (sb_secret_...). Nothing in Cardwise uses it."
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROD_REF}/settings/api-keys"
ask SUPABASE_PROD_PUBLISHABLE_KEY "Paste the cardwise-prod publishable key (sb_publishable_...):"
write_env SUPABASE_PROD_PUBLISHABLE_KEY "$SUPABASE_PROD_PUBLISHABLE_KEY"
open_url "https://supabase.com/dashboard/project/${SUPABASE_DEV_REF}/settings/api-keys"
ask SUPABASE_DEV_PUBLISHABLE_KEY "Paste the cardwise-dev publishable key:"
write_env SUPABASE_DEV_PUBLISHABLE_KEY "$SUPABASE_DEV_PUBLISHABLE_KEY"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Supabase: connect the repo to cardwise-prod"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROD_REF}/settings/integrations"
step "GitHub Integration -> Authorize GitHub -> Authorize Supabase."
step "Install the Supabase app on Cardwise-ai, 'Only select repositories' -> cardwise."
step "Repository Cardwise-ai/cardwise, working directory '.', production branch main."
step "Deploy to production ON. Automatic branching OFF. Enable integration."
pause "Done? Press Enter"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROD_REF}/database/migrations"
say "Wait a minute, then refresh. You should see 20261121120000_init."
if confirm "Is the migration list still empty? (push an empty commit to main to trigger a deploy)"; then
  git commit --allow-empty -q -m "Trigger Supabase production deploy"
  git push -q
  say "Pushed. Refresh the migrations page in a minute."
fi
pause "Once 20261121120000_init is listed (and Storage shows raw-snapshots), press Enter"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Supabase: migrate cardwise-dev"
say "This runs the Supabase CLI: login (browser), link (asks for the dev DB password), db push."
note "In Git Bash the CLI's own prompts can be invisible, so the wizard asks instead."
if confirm "Apply the repo's migrations to cardwise-dev now?"; then
  if ! pnpm exec supabase projects list >/dev/null 2>&1; then
    open_url "https://supabase.com/dashboard/account/tokens"
    step "Generate new token, name it cardwise-cli. Copy it."
    ask_secret SUPABASE_CLI_TOKEN "Paste the access token (hidden, not saved):"
    pnpm exec supabase login --token "$SUPABASE_CLI_TOKEN" </dev/null
  fi
  ask_secret SUPABASE_DEV_DB_PASSWORD "Paste the cardwise-dev database password (hidden, not saved):"
  SUPABASE_DB_PASSWORD="$SUPABASE_DEV_DB_PASSWORD" \
    pnpm exec supabase link --project-ref "$SUPABASE_DEV_REF" </dev/null
  SUPABASE_DB_PASSWORD="$SUPABASE_DEV_DB_PASSWORD" pnpm exec supabase db push --yes </dev/null
fi
open_url "https://supabase.com/dashboard/project/${SUPABASE_DEV_REF}/storage/buckets"
step "New bucket: raw-snapshots, Public OFF, restrict file size to 50 MB. Save."
pause "Done? Press Enter"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Vercel: web project"
open_url "https://vercel.com/new"
step "Sign up with GitHub on the Hobby plan, if you haven't."
step "Import Git Repository -> install the Vercel app on Cardwise-ai,"
step "'Only select repositories' -> cardwise. Import cardwise."
step "Project name cardwise-web, framework Next.js, root directory apps/web. Deploy."
ask WEB_PROD_URL "Paste the production URL (https://...vercel.app):"
WEB_PROD_URL="${WEB_PROD_URL%/}"
write_env WEB_PROD_URL "$WEB_PROD_URL"
note "The scope is the team slug in vercel.com/<scope>/cardwise-web"
ask VERCEL_SCOPE "Paste your Vercel scope:"
write_env VERCEL_SCOPE "$VERCEL_SCOPE"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Vercel: web project settings"
open_url "https://vercel.com/${VERCEL_SCOPE}/cardwise-web/settings/functions"
step "Function region: Washington, D.C. (iad1). Save."
open_url "https://vercel.com/${VERCEL_SCOPE}/cardwise-web/settings/deployment-protection"
step "Vercel Authentication: Standard Protection. Save."
pause "Done? Press Enter"

# ── 9 ─────────────────────────────────────────────────────────────────────
VERCEL=(npx --yes vercel@66)
WEB_VARS_SET=0

# vercel_env NAME ENVIRONMENTS VALUE sets a cardwise-web variable, overwriting
# any existing one, so re-runs are safe.
vercel_env() {
  if printf '%s' "$3" | "${VERCEL[@]}" env add "$1" --environment "$2" \
      --project cardwise-web --scope "$VERCEL_SCOPE" --no-sensitive --force --yes >/dev/null 2>&1; then
    printf '  %s✓ set%s Vercel %s (%s)\n' "$GREEN" "$RESET" "$1" "$2"
    WEB_VARS_SET=$((WEB_VARS_SET + 1))
  else
    SKIPPED+=("Vercel cardwise-web $1 ($2)")
    warn "couldn't set $1 ($2) through the Vercel CLI"
  fi
}

stage "Vercel: web environment variables"
say "The wizard sets these on cardwise-web with the Vercel CLI."
say "Production points at cardwise-prod; Preview and Development at cardwise-dev."
if ! "${VERCEL[@]}" whoami >/dev/null 2>&1; then
  say "Log in to the Vercel CLI first (a browser window opens)."
  "${VERCEL[@]}" login
fi
vercel_env NEXT_PUBLIC_SUPABASE_URL production "$SUPABASE_PROD_URL"
vercel_env NEXT_PUBLIC_SUPABASE_URL preview,development "$SUPABASE_DEV_URL"
vercel_env NEXT_PUBLIC_SUPABASE_ANON_KEY production "$SUPABASE_PROD_PUBLISHABLE_KEY"
vercel_env NEXT_PUBLIC_SUPABASE_ANON_KEY preview,development "$SUPABASE_DEV_PUBLISHABLE_KEY"
note "NEXT_PUBLIC_API_URL waits until the API project exists."
open_url "https://vercel.com/${VERCEL_SCOPE}/cardwise-web/settings/environment-variables"
if (( WEB_VARS_SET < 4 )); then
  warn "Add the missing ones on this page by hand:"
  note "  NEXT_PUBLIC_SUPABASE_URL       Production: $SUPABASE_PROD_URL"
  note "                                 Preview, Development: $SUPABASE_DEV_URL"
  note "  NEXT_PUBLIC_SUPABASE_ANON_KEY  Production: $SUPABASE_PROD_PUBLISHABLE_KEY"
  note "                                 Preview, Development: $SUPABASE_DEV_PUBLISHABLE_KEY"
fi
step "Check that both variables are listed for all three environments."
note "They reach the build on the next deploy; nothing reads them until the chat UI lands."
pause "Looks right? Press Enter"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Supabase: sign-in settings (both projects)"
for ref in "$SUPABASE_PROD_REF" "$SUPABASE_DEV_REF"; do
  [[ "$ref" == "$SUPABASE_PROD_REF" ]] && name="cardwise-prod" || name="cardwise-dev"
  say "$name"
  open_url "https://supabase.com/dashboard/project/${ref}/auth/providers"
  step "Allow new users to sign up: OFF. Email provider ON, Confirm email OFF."
  step "Every other provider OFF."
  open_url "https://supabase.com/dashboard/project/${ref}/auth/url-configuration"
  if [[ "$ref" == "$SUPABASE_PROD_REF" ]]; then
    step "Site URL: ${WEB_PROD_URL}"
    step "Redirect URLs: add ${WEB_PROD_URL}/**"
  else
    step "Site URL: http://localhost:3000"
    step "Redirect URLs: add http://localhost:3000/**"
    step "and https://cardwise-web-*-${VERCEL_SCOPE}.vercel.app/**"
  fi
  pause "Saved for $name? Press Enter"
done

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Supabase: create accounts"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROD_REF}/auth/users"
step "Add user -> Create new user. Email + generated password, tick Auto Confirm User."
step "Create one for yourself, and one per tester."
note "Send testers their password through a password manager share or Signal."
open_url "https://supabase.com/dashboard/project/${SUPABASE_DEV_REF}/auth/users"
step "Create one for yourself in cardwise-dev too."
pause "Done? Press Enter"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Model providers: development keys"
say "Production keys are created later, together with the API project."
open_url "https://aistudio.google.com/apikey"
step "Create API key -> in a new Google Cloud project named cardwise. Name it cardwise-dev."
warn "Do not enable billing on that Google Cloud project."
ask_secret GEMINI_DEV_API_KEY "Paste the Gemini key (hidden):"
open_url "https://openrouter.ai/settings/keys"
step "Create key cardwise-dev with credit limit 0. Don't buy credits."
ask_secret OPENROUTER_DEV_API_KEY "Paste the OpenRouter key (hidden):"
# The local API reads .env; .env.hosted keeps the record of the hosted setup.
for ENV_FILE in .env.hosted .env; do
  write_env CARDWISE_GEMINI_API_KEY "$GEMINI_DEV_API_KEY"
  write_env CARDWISE_OPENROUTER_API_KEY "$OPENROUTER_DEV_API_KEY"
done
ENV_FILE=".env.hosted"
open_url "https://openrouter.ai/settings/privacy"
step "Allow providers that may train on inputs (needed for most :free models)."
pause "Done? Press Enter"

finish
say "Send these back in chat (none are secret):"
note "  prod ref:  $SUPABASE_PROD_REF"
note "  dev ref:   $SUPABASE_DEV_REF"
note "  web URL:   $WEB_PROD_URL"
note "  scope:     $VERCEL_SCOPE"
printf '\n'
